'use strict'

import resource from '../../resource'
import { TILE_WIDTH, TILE_HEIGHT, ENEMY_LEEVER_RED, ENEMY_LEEVER_BLUE, DIRECTION_SOUTH } from '../../constant'
import { Enemy, DIRECTION_VECTORS, DIRECTIONS, STATE_HURT, randomInt, pick, drawImage, directionOf } from './common'

// Sand creatures: they come out, spin around, then sink. Under the sand, they cannot be hit and
// do not hurt. The red ones come out in front of Link and rush straight on, the blue ones anywhere
const LEEVERS = {
  [ENEMY_LEEVER_RED]: { color: 'red', life: 2, contactDamage: 0.5, speed: 1, inFrontOfLink: true },
  [ENEMY_LEEVER_BLUE]: { color: 'blue', life: 4, contactDamage: 1, speed: 1, inFrontOfLink: false }
}
const MIN_UNDER_STEPS = 40
const MAX_UNDER_STEPS = 140
const RISE_STEPS = 24
const MIN_OUT_STEPS = 150
const MAX_OUT_STEPS = 260
const SPIN_FRAME_STEPS = 4
const SAND_FRAME_STEPS = 12
// Blue ones change their way every so many steps
const TURN_STEPS = 48
// How far in front of Link a red one comes out, in tiles
const AHEAD = 3
const TRIES = 12

const STATE_UNDER = 'under'
const STATE_RISING = 'rising'
const STATE_OUT = 'out'
const STATE_SINKING = 'sinking'

class Leever extends Enemy {
  constructor (type, x, y, random = Math.random) {
    const config = LEEVERS[type]
    super(type, x, y, config, random)
    this.config = config
    this.direction = pick(random, DIRECTIONS)
    this.wait = 0
    this.setState(STATE_UNDER)
    this.wait = randomInt(random, MIN_UNDER_STEPS, MAX_UNDER_STEPS)
  }

  get isActive () {
    return [STATE_OUT, STATE_HURT].includes(this.state)
  }

  // A tile to come out at: in front of Link (red; anywhere when there is no room there), or
  // anywhere free (blue)
  placeToRise (map, link) {
    for (let i = 0; i < TRIES; i++) {
      let x, y
      if (this.config.inFrontOfLink && i < TRIES / 2) {
        // Link's directions are named as the enemies' ones
        const [dx, dy] = DIRECTION_VECTORS[link.direction] ?? DIRECTION_VECTORS[DIRECTION_SOUTH]
        const along = randomInt(this.random, AHEAD - 1, AHEAD + 1)
        x = Math.round((link.x - map.x) / TILE_WIDTH + dx * along) * TILE_WIDTH + map.x
        y = Math.round((link.y - map.y) / TILE_HEIGHT + dy * along) * TILE_HEIGHT + map.y
      } else {
        x = map.x + randomInt(this.random, 0, map.width / TILE_WIDTH - 1) * TILE_WIDTH
        y = map.y + randomInt(this.random, 0, map.height / TILE_HEIGHT - 1) * TILE_HEIGHT
      }
      if (this.canStandAt(map, x, y)) {
        return { x, y }
      }
    }
    return undefined
  }

  move (map, link) {
    if (this.config.inFrontOfLink) {
      // Straight at Link, from where it came out
      if (this.steps === 1) {
        this.direction = directionOf(link.x - this.x, link.y - this.y)
      }
    } else if (this.steps % TURN_STEPS === 0) {
      this.direction = pick(this.random, DIRECTIONS)
    }
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    for (let i = 0; i < this.config.speed; i++) {
      if (!this.canStandAt(map, this.x + dx, this.y + dy)) {
        // Back into the sand at a wall
        this.setState(STATE_SINKING)
        return
      }
      this.x += dx
      this.y += dy
    }
  }

  act (map, link) {
    switch (this.state) {
      case STATE_UNDER:
        if (this.steps >= this.wait) {
          const place = this.placeToRise(map, link)
          if (!place) {
            this.setState(STATE_UNDER)
            return
          }
          this.x = place.x
          this.y = place.y
          this.setState(STATE_RISING)
        }
        break
      case STATE_RISING:
        if (this.steps >= RISE_STEPS) {
          this.setState(STATE_OUT)
          this.wait = randomInt(this.random, MIN_OUT_STEPS, MAX_OUT_STEPS)
        }
        break
      case STATE_OUT:
        this.move(map, link)
        if (this.state === STATE_OUT && this.steps >= this.wait) {
          this.setState(STATE_SINKING)
        }
        break
      case STATE_SINKING:
        if (this.steps >= RISE_STEPS) {
          this.setState(STATE_UNDER)
          this.wait = randomInt(this.random, MIN_UNDER_STEPS, MAX_UNDER_STEPS)
        }
        break
    }
  }

  drawBody (context) {
    switch (this.state) {
      case STATE_UNDER:
        return
      case STATE_RISING:
      case STATE_SINKING: {
        // The mound grows while rising, shrinks while sinking
        const grown = Math.min(1, Math.floor(this.steps / SAND_FRAME_STEPS))
        drawImage(context, resource.getSprite('leever_sand_move'), this.state === STATE_RISING ? grown : 1 - grown, this.x, this.y, this.width, this.height)
        return
      }
    }
    drawImage(context, resource.getSprite(`leever_${this.config.color}_move`), Math.floor(this.steps / SPIN_FRAME_STEPS) % 2, this.x, this.y, this.width, this.height)
  }
}

export { Leever, LEEVERS }
