'use strict'

import soundManager from '../service/sound-manager'
import resource from '../resource'
import { TILE_WIDTH, TILE_HEIGHT, SOUND_SECRET, SECRET_PUSH, SECRET_PUSH_BRACELET, LINK_DIRECTION_NORTH, LINK_DIRECTION_SOUTH } from '../constant'

// Hidden entrances of the overworld, as in the ROM (bank 5, $AABF: the squares $E5-$EA of a screen are
// drawn as a rock, a bush or a grave and become an object $62-$65). See docs/rom-analysis.md

// A pushed rock slides one tile, half an NES pixel a frame: one display pixel a game step
const PUSH_SPEED = 1
// Link must face the rock, not more than this to the side
const PUSH_ALIGNMENT_TOLERANCE = TILE_WIDTH / 4

// The hidden entrances of the screen
export function * secretTiles (map) {
  for (const tile of map.tilesIterator()) {
    if (tile.isHidden) {
      yield tile
    }
  }
}

// What a bomb or a flame at box opens (kind: SECRET_BOMB or SECRET_FLAME): the hidden entrance of that
// kind less than a tile away (measured in the ROM: a bomb 8 NES pixels to the side still opens the
// wall, 16 does not). True if one opened
export function revealAt (map, box, kind) {
  let revealed = false
  for (const tile of [...secretTiles(map)]) {
    if (tile.destructible !== kind) {
      continue
    }
    if (Math.abs(tile.x - box.x) < TILE_WIDTH && Math.abs(tile.y - box.y) < TILE_HEIGHT) {
      tile.reveal()
      revealed = true
    }
  }
  if (revealed) {
    soundManager.play(resource.getSound(SOUND_SECRET))
  }
  return revealed
}

// The hidden entrance a push of this tile opens, if Link can push it
function findPushSecret (map, block, link) {
  for (const tile of secretTiles(map)) {
    const { x, y } = tile.secret?.block ?? {}
    if (x !== block.column || y !== block.line) {
      continue
    }
    if (tile.destructible === SECRET_PUSH || (tile.destructible === SECRET_PUSH_BRACELET && link.inventory.powerBracelet)) {
      return tile
    }
  }
}

// Link walking against a rock or a grave that hides an entrance pushes it one tile up or down (never
// sideways, measured in the ROM), if the tile behind is free. It starts at once and slides at its own speed
export function tryPush (map, link) {
  if (map.pushes.length > 0 || (link.direction !== LINK_DIRECTION_NORTH && link.direction !== LINK_DIRECTION_SOUTH)) {
    return
  }
  const dy = link.direction === LINK_DIRECTION_NORTH ? -1 : 1
  const hitbox = link.getHitbox()
  const column = Math.floor((link.x + link.width / 2 - map.x) / TILE_WIDTH)
  const line = Math.floor(((dy < 0 ? hitbox.y - 1 : hitbox.y + hitbox.height + 1) - map.y) / TILE_HEIGHT)
  const block = map.getTile(column, line)
  if (!block || Math.abs(link.x - block.x) > PUSH_ALIGNMENT_TOLERANCE) {
    return
  }
  const entrance = findPushSecret(map, block, link)
  const target = map.getTile(column, line + dy)
  if (!entrance || !target || target.blockPoints.length > 0 || target.isHidden) {
    return
  }
  map.pushes.push(new Push(block, target, entrance))
}

// A rock sliding from its tile to the next one; the entrance opens when it is there
export class Push {
  constructor (block, target, entrance) {
    this.block = block
    this.target = target
    this.entrance = entrance
    this.sprite = block.sprite
    this.offset = 0
    this.done = false
    // Both tiles block while it slides; the one it leaves shows the ground behind it
    block.sprite = target.sprite
    target.setHitbox(block.hitbox)
  }

  process () {
    this.offset += PUSH_SPEED
    if (this.offset < TILE_HEIGHT) {
      return
    }
    this.target.sprite = this.sprite
    this.block.setHitbox(this.target.original.hitbox)
    this.entrance.reveal()
    soundManager.play(resource.getSound(SOUND_SECRET))
    this.done = true
  }

  draw (context) {
    const sign = Math.sign(this.target.y - this.block.y)
    this.sprite.draw(context, this.block.x, this.block.y + sign * this.offset, this.block.width, this.block.height)
  }
}

// Leaving the screen: the pushed rocks go back where they were, the entrances found stay open (the ROM
// keeps them in the flags of the screen, $067F + screen)
export function restoreSecrets (map) {
  for (const tile of map.tilesIterator()) {
    if (tile.sprite !== tile.original.sprite || tile.hitbox !== tile.original.hitbox) {
      tile.restore()
    }
  }
}
